CLAIM_DATA = {'TBDY2018_TABLE4_1_A11': (('TBDY2018_TABLE4_1_A11',), 'v1', 'A11 cast-in-place RC Table 4.1 baseline policy is ductility=HIGH, R=8, D=3, permitted BYS classes satisfy BYS>=3.', 'sha256:990c4d15fff7d89c63671e87451561850371888f7e4ef7616e4f828fd994ace6'), 'TBDY2018_TABLE4_1_A12': (('TBDY2018_TABLE4_1_A12',), 'v1', 'A12 cast-in-place RC Table 4.1 baseline policy is ductility=HIGH, R=7, D=2.5, permitted BYS classes satisfy BYS>=2.', 'sha256:fc833735ce1df90578e945938683c9f2328346a0e49165eb5aa76ea838783251'), 'TBDY2018_TABLE4_1_A13': (('TBDY2018_TABLE4_1_A13',), 'v1', 'A13 cast-in-place RC Table 4.1 baseline policy is ductility=HIGH, R=6, D=2.5, permitted BYS classes satisfy BYS>=2.', 'sha256:bb6a5545c4af3666c733869f28f293a171a15c7f65cec1b99fbdad65d8842263'), 'TBDY2018_TABLE4_1_A14': (('TBDY2018_TABLE4_1_A14',), 'v1', 'A14 cast-in-place RC Table 4.1 baseline policy is ductility=HIGH, R=8, D=2.5, permitted BYS classes satisfy BYS>=2.', 'sha256:e04fcc74d5a5d034bb4d5f2490e4d2a342e4d103d90e42ce7239a01ddf571e50'), 'TBDY2018_TABLE4_1_A15': (('TBDY2018_TABLE4_1_A15',), 'v1', 'A15 cast-in-place RC Table 4.1 baseline policy is ductility=HIGH, R=7, D=2.5, permitted BYS classes satisfy BYS>=2.', 'sha256:eb78f1abc7070d3ee074e485f99b0de5271326a7c9b931cd305a06d207315341'), 'TBDY2018_TABLE4_1_A16': (('TBDY2018_TABLE4_1_A16',), 'v1', 'A16 is the high-ductility one-storey cast-in-place RC column system with R=3, D=2, building height not exceeding 12 m, and pinned roof-level connections; the ordinary Table 4.1 BYS lookup is not used.', 'sha256:f48affae8cbe55b1273bbfb168e621a254dcacf14f4e6310a106c7c3f800e699'), 'TBDY2018_TABLE4_1_A21': (('TBDY2018_TABLE4_1_A21',), 'v1', 'A21 cast-in-place RC Table 4.1 baseline policy is ductility=MIXED, R=6, D=2.5, permitted BYS classes satisfy BYS>=4.', 'sha256:439cf5bdde2f64ac9c840f41ec815e89e23d8841e6a4080492dc6e4fd3834de7'), 'TBDY2018_TABLE4_1_A22': (('TBDY2018_TABLE4_1_A22',), 'v1', 'A22 cast-in-place RC Table 4.1 baseline policy is ductility=MIXED, R=5, D=2.5, permitted BYS classes satisfy BYS>=4.', 'sha256:3fd21b66368db4f3b4477e3f0f51792ecc092e77972ffbe135862fea47fac416'), 'TBDY2018_TABLE4_1_A23': (('TBDY2018_TABLE4_1_A23',), 'v1', 'A23 cast-in-place RC Table 4.1 baseline policy is ductility=MIXED, R=6, D=2.5, permitted BYS classes satisfy BYS>=6.', 'sha256:11e6e0d48d10e70e493233e32d554d0b58e46cc0b5b80e6de1998272b90066c2'), 'TBDY2018_TABLE4_1_A24': (('TBDY2018_TABLE4_1_A24',), 'v1', 'A24 cast-in-place RC Table 4.1 baseline policy is ductility=MIXED, R=5, D=2.5, permitted BYS classes satisfy BYS>=6.', 'sha256:6dc3ef7202bbd133d134306bf47bee9f7714a1dd09b66eeaf5f22e2991dd5194'), 'TBDY2018_TABLE4_1_A31': (('TBDY2018_TABLE4_1_A31',), 'v1', 'A31 cast-in-place RC Table 4.1 baseline policy is ductility=LIMITED, R=4, D=2.5, permitted BYS classes satisfy BYS>=7.', 'sha256:ce172bccebb566544011410ce07d163062c8ef3825c93609d7004c56dcd931e2'), 'TBDY2018_TABLE4_1_A32': (('TBDY2018_TABLE4_1_A32',), 'v1', 'A32 cast-in-place RC Table 4.1 baseline policy is ductility=LIMITED, R=4, D=2, permitted BYS classes satisfy BYS>=6.', 'sha256:c3db7396f000b7dd66583fd62ed0a1ce00ef2a9e1637679eaee32c271da2335a'), 'TBDY2018_TABLE4_1_A33': (('TBDY2018_TABLE4_1_A33',), 'v1', 'A33 cast-in-place RC Table 4.1 baseline policy is ductility=LIMITED, R=4, D=2, permitted BYS classes satisfy BYS>=6.', 'sha256:d6eb87deabec48167e74f9b7f55d55319dc265c67b21ef44926ee566ad0e361c'), 'TBDY2018_4_3_1_2_A21_A22_DTS4_BYS': (('TBDY2018_4_3_1_2',), 'v1', 'For A21 and A22, only when DTS=4, the permitted building height class may be relaxed to BYS>=2.', 'sha256:91c360212669f1d2b9601fe14021963a52fdf94a8ef46f20d1701f6903ab6c27'), 'TBDY2018_4_3_2_1_TABLE4_1_RD': (('TBDY2018_4_3_2_1',), 'v1', 'Structural system behavior coefficient R and overstrength coefficient D are taken from Table 4.1 for the applicable structural system and ductility level.', 'sha256:39069c8824df076e100e2758a0be51017a0415cf25070ed09cdccebd41b2dd11'), 'TBDY2018_4_3_2_4_WALL_DISTRIBUTION_R_POLICY': (('TBDY2018_4_3_2_4',), 'v1', 'For DTS 1,1a,2,2a RC-wall and/or steel-braced buildings, failure of either specified distribution condition requires (4/5)R in that direction while D is unchanged; VS-4A therefore treats the final R as pending post-analysis qualification where this clause applies.', 'sha256:ceff776f6e1323838efb1928000b02e5baa8ce7be054fe469b290403174dd5c4'), 'TBDY2018_4_3_3_1_DUCTILITY_CLASSES': (('TBDY2018_4_3_3_1',), 'v1', 'Structural systems are classified by Table 4.1 into high, limited, or mixed ductility levels.', 'sha256:edb53571a81ca02ecabc9bd473b589b1492591cc2c34631a67db6c444e54d7ad'), 'TBDY2018_4_3_4_1_LIMITED_DTS': (('TBDY2018_4_3_4_1',), 'v1', 'Limited-ductility structural systems are prohibited for DTS=1a,2a,3a,4a.', 'sha256:7cc2ec957cab05ed8d96d5bb8b2dd973b48993e8d7be8f72dc12ed2218d5c080'), 'TBDY2018_4_3_4_1_MIXED_DTS_BYS': (('TBDY2018_4_3_4_1',), 'v1', 'Mixed-ductility structural systems are prohibited for DTS=1a or 2a when BYS<=6.', 'sha256:7a19f18a6603026940b0532b3f8f6b846a59539ef529b44f3f0cfaaf50399061'), 'TBDY2018_4_3_4_2_ORTHOGONAL_DUCTILITY': (('TBDY2018_4_3_4_2',), 'v1', 'Orthogonal structural systems must have the same ductility level; different R values and their corresponding D values may be used by direction.', 'sha256:bf0b93e06bd2fac88a9024a779db1143bb45be4401db4c42ef93ac471213c717'), 'TBDY2018_4_3_4_3_A31_DTS': (('TBDY2018_4_3_4_3',), 'v1', 'A31 limited-ductility RC moment-frame-only systems may be used only for DTS=3 or DTS=4.', 'sha256:ef2a0aba405d354482701ef518dbac397d169a47522fd38b55084976b0dedec7'), 'TBDY2018_4_3_4_5_HIGH_COMBINED_QUALIFICATION': (('TBDY2018_4_3_4_5',), 'v1', 'High-ductility frame plus high wall/braced systems require the post-analysis overturning-moment distribution qualification of 4.3.4.5; VS-4A does not resolve that calculation.', 'sha256:0d6d38f772f8215196001ed3c27521e13d448ee344ef1c8b64f80c18c6bf269f'), 'TBDY2018_4_3_4_6_MIXED_QUALIFICATION': (('TBDY2018_4_3_4_6',), 'v1', 'Mixed-ductility systems require the post-analysis overturning-moment distribution qualification of 4.3.4.6; VS-4A does not resolve that calculation.', 'sha256:5b8c5f8cf1911963367f2c727454951e18bf0c0e8050fa2d0f91636284ffc41c'), 'TBDY2018_4_3_4_7_LIMITED_WALL_FRAME_QUALIFICATION': (('TBDY2018_4_3_4_7',), 'v1', 'Limited wall plus limited moment-frame systems require the 4.3.4.7 post-analysis qualification; VS-4A does not resolve that calculation.', 'sha256:da3944c74229475733340123f535cf1e0ac8ddc44b1c535ef3c8087fbc985b28'), 'TBDY2018_4_3_4_8_MDEV_MO_DEFERRED': (('TBDY2018_4_3_4_8',), 'v1', 'MDEV and Mo used by 4.3.2.4, 4.3.4.5 and 4.3.4.6 are obtained by the methods referenced in 4.3.4.8; formal derivation is deferred to VS-4B.', 'sha256:8cc9203c2a196278d3fd099b7c1441d7db57ecda11786f7ceb4f0df83aa4847d'), 'TBDY2018_VS4A_PREANALYSIS_ELIGIBILITY_COMPOSITION': (('TBDY2018_4_3_1_2', 'TBDY2018_4_3_4_1', 'TBDY2018_4_3_4_3', 'TBDY2018_TABLE4_1_A16'), 'v1', 'For the bounded VS-4A cast-in-place RC system declaration, directional pre-analysis eligibility is ELIGIBLE only when all applicable source-bound BYS, DTS, A31 and A16 eligibility prerequisites are satisfied; any proven violation is INELIGIBLE and unresolved mandatory reviewed evidence is BLOCKED.', 'sha256:a06e9da2bea75a5bd59f6fe898ea4367c05eeddd6a978f5a719dd209b6dff65f'), 'TBDY2018_VS4A_BASELINE_POLICY_LIFECYCLE': (('TBDY2018_4_3_1_2', 'TBDY2018_4_3_2_1', 'TBDY2018_4_3_2_4', 'TBDY2018_4_3_4_1', 'TBDY2018_4_3_4_3', 'TBDY2018_4_3_4_5', 'TBDY2018_4_3_4_6', 'TBDY2018_4_3_4_7', 'TBDY2018_TABLE4_1_A16'), 'v1', 'The VS-4A directional Table 4.1 baseline policy is RESOLVED only when pre-analysis eligibility is ELIGIBLE and no applicable post-analysis qualification remains pending; post-analysis qualification makes the baseline PROVISIONAL, proven ineligibility makes it INVALID, and blocked mandatory evidence leaves it UNRESOLVED.', 'sha256:9af020c7eebb734982ccf994a05ca25c6a0e1c465c010d3ca592da9b8296eb81'), 'TBDY2018_VS4A_ANALYSIS_BASIS_COMPATIBILITY': (('TBDY2018_4_3_1_2', 'TBDY2018_4_3_2_1', 'TBDY2018_4_3_2_4', 'TBDY2018_4_3_4_1', 'TBDY2018_4_3_4_3', 'TBDY2018_4_3_4_5', 'TBDY2018_4_3_4_6', 'TBDY2018_4_3_4_7', 'TBDY2018_TABLE4_1_A16'), 'v2', 'Analysis-basis compatibility is INVALID for proven pre-analysis ineligibility, UNRESOLVED for blocked pre-analysis evidence or pending post-analysis qualification, MATCH only for an eligible resolved directional policy exactly matching the reviewed analysis assumption, and REANALYSIS_REQUIRED for an eligible resolved mismatch.', 'sha256:d5a151e4e4bb23ae929c4058de4192bcf7e7d92d1d68a640f6e4020e4ffd5895')}

